```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^(adjective)$/)) {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    const firstAdjective = adjectives.shift();
    adjectives.push(firstAdjective);
    const newSentence = words.join(" ") + " " + adjectives.join(" ");
    return newSentence;
  } else {
    return sentence;
  }
}

const inputSentence = "Beautiful green trees are in the park";
const outputSentence = switchAdjectives(inputSentence);
console.log(outputSentence); // Output: Green beautiful trees are in the park
```

```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^(adjective)$/)) {
      adjectives.push(words[i]);
    }
  }

  const newSentence = words.filter(word => !adjectives.includes(word)).join(' ') + ' ' + adjectives.join(' ');

  return newSentence;
}

const sentence = "Beautiful green trees are in the park";
const result = switchAdjectives(sentence);
console.log(result); // Output: Green beautiful trees are in the park
```

Here's a simple JavaScript function that will switch the order of adjectives in a sentence:

```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^(\w+)\b\s*$/)) {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    return `${adjectives[1]} ${adjectives[0]} ${words.slice(2).join(" ")}`;
  } else {
    return sentence;
  }
}

const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park
```

