Here's a C++ program that uses a recursive function to generate the Fibonacci sequence:

```cpp
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3;
    int sequenceLength;

    cout << "Enter the first two numbers in the Fibonacci sequence: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (num1 < 0 || num2 < 0) {
        cout << "Error: Both numbers must be non-negative." << endl;
        return 1;
    }

    cout << "Enter the length of the Fibonacci sequence: ";
    cin >> sequenceLength;

    if (sequenceLength < 1) {
        cout << "Error: The length of the sequence must be at least 1." << endl;
        return 1;
    }

    int result = fibonacci(sequenceLength, num1, num2);

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequenceLength; i++) {
        cout << result << ", ";
        result = fibonacci(sequenceLength - i - 1, num2, result);
    }
    cout << endl;

    return 0;
}
```

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3;
    int count;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (iss.fail()) {
        throw runtime_error("Invalid input");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> count;

    if (count < 1) {
        throw runtime_error("Invalid input");
    }

    try {
        num3 = fibonacci(count, num1, num2);
        cout << "Fibonacci sequence (" << count << " elements):";
        for (int i = 0; i < count; i++) {
            cout << num3 << (i < count - 1 ? ", " : "");
            num3 = num3 + fibonacci(count - 1 - i, num2, num3);
        }
        cout << endl;
    } catch (runtime_error& e) {
        cerr << "Error: " << e.what() << endl;
    }

    return 0;
}
```

