const { NestFactory } = require('@nestjs/core');
const { TypeOrmModule } = require('@nestjs/typeorm');
const { PermissionGuard } = './permission.guard';
const { UserRole } = './user-role.enum';
const { Permission } = './permission.entity';

const app = await NestFactory.create(async (app) => {
  app.useGlobalGuards(new PermissionGuard());

  const dbOptions = {
    type: 'mysql',
    host: 'localhost',
    port: 3306,
    username: 'root',
    password: 'password',
    database: 'mydatabase',
    entities: [__dirname + '/entities/**/*.ts'],
    synchronize: true,
  };

  await app.connect(dbOptions);
});

export default app;
```

In this example, we have created an application using Nest.js and TypeORM. We have also created a `PermissionGuard` class that implements the `CanActivate` interface to guard access to resources based on user roles and permissions. The `UserRole` enum defines the available user roles, and the `Permission` entity represents the permissions associated with each role.

The `app.useGlobalGuards()` method is used to register the `PermissionGuard` as a global guard for the application. This means that all requests to the application will be subject to the permission guard's authorization checks.

The `dbOptions` object configures the connection to the MySQL database. The `entities` property specifies the directory where the entity classes are located. The `synchronize` property sets the synchronization mode for the database schema.

Finally, the `export default app` statement exports the application instance so that it can be imported and used in other parts of the application.

