      <input type="number" id="input-temp" value={inputTemp} onChange={(e) => setInputTemp(e.target.value)} />
      <label htmlFor="output-unit">Select an output unit:</label>
      <select id="output-unit" value={selectedUnit} onChange={(e) => setSelectedUnit(e.target.value)}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
      </select>
      <button onClick={() => setOutputTemp(convertTemp(inputTemp, selectedUnit))}>Convert</button>
      <p>Result: {outputTemp}</p>
    </form>
  </div>
);
```

5. Export the component:

```javascript
export default TemperatureConverter;
```

Here's a simple React component using hooks to convert between different temperature units:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('Celsius');

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  const convertTemperature = () => {
    if (unit === 'Celsius') {
      return (temperature * 9 / 5) + 32;
    } else if (unit === 'Fahrenheit') {
      return (temperature - 32) * 5 / 9;
    } else {
      return temperature;
    }
  };

  return (
    <div>
      <label htmlFor="temperature">Enter temperature:</label>
      <input type="number" id="temperature" value={temperature} onChange={handleInputChange} />
      <label htmlFor="unit">Select unit:</label>
      <select id="unit" value={unit} onChange={handleUnitChange}>
        <option value="Celsius">Celsius</option>
        <option value="Fahrenheit">Fahrenheit</option>
      </select>
      <p>Converted temperature: {convertTemperature().toFixed(2)} {unit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

