Here's a simple Go program that parses a struct in a Go source file and generates an AVRO schema from it. Save this code as `go_to_avro.go`:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/v2/schema"
)

func main() {
	sourceFile := "your_go_source_file.go"
	structName := "YourStructName"
	outputFile := "struct.avsc"

	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Println("Error reading source file:", err)
		return
	}

	// Extract the struct definition from the Go source file
	re := regexp.MustCompile(`type (\w+)\{`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) != 2 {
		fmt.Println("Error extracting struct definition")
		return
	}

	structType := matches[1]

	// Generate the AVRO schema
	avroSchema, err := schema.Parse(fmt.Sprintf(`{
		"namespace": "your_namespace",
		"type": "%s",
