```python
import datetime

class PomodoroTimer:
    def __init__(self, individual_productivity_level, max_intervals_per_day, work_style):
        self.productivity_level = individual_productivity_level
        self.max_intervals_per_day = max_intervals_per_day
        self.work_style = work_style
        self.current_interval = 1
        self.break_duration = 5
        self.long_break_duration = 15

    def calculate_optimal_interval_length(self):
        return round(self.productivity_level * 25)

    def schedule_work_intervals(self):
        work_intervals = []
        for i in range(self.max_intervals_per_day):
            if self.work_style == "focused":
                work_intervals.append(f"Work interval {i+1}: {self.calculate_optimal_interval_length()} minutes")
                work_intervals.append("Short break: 5 minutes")
            else:
                work_intervals.append(f"Work interval {i+1}: {self.calculate_optimal_interval_length()} minutes")
                work_intervals.append("Long break: 10 minutes")
        work_intervals.pop()  # remove last short break
        work_intervals.append("Long break: 15 minutes")
        return work_intervals

    def start_timer(self):
        while self.current_interval <= self.max_intervals_per_day:
            print(f"Current interval: {self.current_interval}")
            self.current_interval += 1
            self.perform_work_interval()
            self.take_break()

    def perform_work_interval(self):
        print("Starting work interval...")
        work_time = self.calculate_optimal_interval_length()
        start_time = datetime.datetime.now

