To retrieve the username from the JWT token in ASP.NET C# WebAPI, you can use the `JwtSecurityToken` class to decode the token and extract the username claim. Here's an example:
```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public static string GetUsernameFromJwtToken(string token)
{
    var tokenHandler = new JwtSecurityTokenHandler();
    var key = Encoding.ASCII.Parse("your_secret_key");
    var tokenValidationParameters = new TokenValidationParameters
    {
        IssuerSigningKey = key,
        ValidateIssuer = false,
        ValidateAudience = false,
        ValidateLifetime = true,
        ClockSkew = TimeSpan.Zero
    };
    var securityToken = tokenHandler.ReadJwtToken(token, tokenValidationParameters);
    var usernameClaim = securityToken.Claims.FirstOrDefault(c => c.Type == "username");
    return usernameClaim?.Value;
}
```
Replace `"your_secret_key"` with your application's secret key. This method takes a JWT token as input and returns the username claim value if found, or null otherwise.

To retrieve the username from the JWT token in ASP.NET C# WebAPI, you can use the `ClaimsPrincipal` class and the `GetClaim()` method to extract the claim with the desired name. Here's an example:
```csharp
using System;
using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace WebApiJwtExample.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    public class ValuesController : ControllerBase
    {
        [HttpGet]
        public ActionResult Get()
        {
            var userName = GetUserNameFromToken();
            return Ok(new { message = $"Hello, {userName}!" });
        }

        private string GetUserNameFromToken()
        {
            var token = Request.Headers["Authorization"].FirstOrDefault();
            if (token == null)
            {
                throw new InvalidOperationException("No token found in the request");
            }

            var claimsPrincipal = new ClaimsPrincipal(new ClaimsIdentity(new[] { new Claim(ClaimTypes.NameIdentifier, token) }));
            var userNameClaim = claimsPrincipal.FindFirst(ClaimTypes.NameIdentifier);
            if (userNameClaim == null || string.IsNullOrEmpty(userNameClaim.Value))
            {
                throw new InvalidOperationException("No user name found in the token");
            }

            return userNameClaim.Value;
        }
    }
}
```
Make sure to install the `Microsoft.AspNetCore.Authorization` package if you haven't already. This example assumes that the token contains a claim with the `ClaimTypes.NameIdentifier` type, which represents the user's name or username. You may need to adjust the code to match your specific token structure.

To retrieve the username from the JWT token in ASP.NET C# WebApi, you can use the `ClaimsPrincipal` object and the `User` property to access the user's claims. Here's an example:

```csharp
using Microsoft.IdentityModel.Tokens;
using System;
using System.Security.Claims;
using System.Threading.Tasks;

namespace WebApiJwtExample
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            // ...

            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = CookieAuthenticationDefaults.AuthenticationScheme;
                options.DefaultSignInScheme = CookieAuthenticationDefaults.AuthenticationScheme;
                options.DefaultChallengeScheme = OpenIdConnectDefaults.AuthenticationScheme;
            })
            .AddCookie()
            .AddOpenIdConnect(options =>
            {
                options.Authority = "https://example.com/auth";
                options.ClientId = "your_client_id";
                options.ClientSecret = "your_client_secret";
                options.ResponseType = "code";
                options.SaveTokens = true;
                options.GetClaimsFromUserInfoEndpoint = true;
                options.UserInformationEndpoint = "https://example.com/userinfo";
                options.ClaimActions.Clear();
                options.ClaimActions.MapJsonKey("username", "sub");
            });

            // ...
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            // ...

            app.UseAuthentication();
            app.UseAuthorization();

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    public class MyController : ControllerBase
    {
        [HttpGet]
        public IActionResult GetUsername()
        {
            var user = HttpContext.User;
            var username = user.FindFirstValue("username");
            return Ok(username);
        }
    }
}
