To achieve this task, you can use the following PHP code:

```php
<?php
// Database connection details
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "database_name";

// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Query to fetch customer information with their purchasing patterns
$sql = "SELECT c.name AS customer_name, COUNT(p.product_id) AS purchase_count, p.product_name AS product_name
        FROM customers c
        JOIN purchases p ON c.customer_id = p.customer_id
        WHERE p.product_name = 'specific_product' AND p.date BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 WEEK) AND CURDATE()
        GROUP BY c.customer_id, p.product_name
        HAVING purchase_count >= 3;";

$result = $conn->query($sql);

if ($result->num_rows > 0) {
    // output data of each row
    while($row = $result->fetch_assoc()) {
        echo "Customer Name: " . $row["customer_name"]. " - Purchase Count: " . $row["purchase_count"]. " - Product Name: " . $row["product_name"]. "<br>";
    }
} else {
    echo "0 results";
}

$conn->close();
?>
```

