Here's a simple example of a toast notification using React Context:

```jsx
import React, { createContext, useEffect } from 'react';

const ToastContext = createContext(null);

function ToastProvider({ children }) {
  const [toastMessage, setToastMessage] = React.useState(null);

  useEffect(() => {
    if (toastMessage) {
      const timeoutId = setTimeout(() => {
        setToastMessage(null);
      }, 3000);

      return () => clearTimeout(timeoutId);
    }
  }, [toastMessage]);

  return (
    <ToastContext.Provider value={{ toastMessage, setToastMessage }}>
      {children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { toastMessage, setToastMessage } = React.useContext(ToastContext);

  function handleClick() {
    setToastMessage('Toast message!');
  }

  return (
    <div>
      {toastMessage && <div>{toastMessage}</div>}
      <button onClick={handleClick}>Show toast</button>
    </div>
  );
}

function App() {
  return (
    <ToastProvider>
      <ToastConsumer />
    </ToastProvider>
  );
}

export default App;
```

In this example, we have a `ToastProvider` component that provides the toast message and a `setToastMessage` function to update it. The `ToastConsumer` component consumes the toast message and a `setToastMessage` function to display and dismiss the toast message. The `App` component wraps everything together and passes the `ToastProvider` down as a context provider.

Here's a simple example of a toast notification using React context:

```javascript
import React, { createContext, useContext } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = React.useState(null);

  function showToast(message) {
    setToast({ message, visible: true });

    setTimeout(() => {
      setToast({ message, visible: false });
    }, 3000);
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { showToast } = useContext(ToastContext);

  return (
    <div>
      <button onClick={() => showToast('Hello, world!')}>Show toast</button>
    </div>
  );
}

export default ToastProvider;
export { ToastConsumer };
```

In this example, we have a `ToastProvider` component that creates a context object and provides a `showToast` function to its child components. The `ToastConsumer` component consumes the context object and uses the `showToast` function to display a toast notification.

