import re

def english_number_representation(num):
    if num < 0:
        return "negative " + english_number_representation(-num)
    elif num == 0:
        return "zero"
    else:
        words = []
        while num > 0:
            words.append(str(num % 10))
            num //= 10
        return " ".join(reversed(words))

def scientific_notation_representation(num):
    if num < 0:
        return "negative " + scientific_notation_representation(-num)
    elif num == 0:
        return "zero"
    else:
        words = []
        while num > 0:
            words.append(str(num % 10))
            num //= 10
        return " ".join(reversed(words))

def language_specific_representation(num, lang):
    if lang == "fr":
        return "nombre " + str(num)
    elif lang == "es":
        return "número " + str(num)
    elif lang == "de":
        return "Zahl " + str(num)
    else:
        return "English representation: " + english_number_representation(num)

def sql_representation(num):
    if num < 0:
        return "negative " + sql_representation(-num)
    elif num == 0:
        return "zero"
    else:
        words = []
        while num > 0:
            words.append(str(num % 10))
            num //= 10
        return " ".join(reversed(words))

