import re

def english_number_to_words(n):
    if n == 0:
        return "zero"
    elif n > 0:
        digits = [int(d) for d in str(n)]
        words = []
        for i, d in enumerate(digits):
            if d == 1:
                words.append("one")
            elif d == 2:
                words.append("two")
            elif d == 3:
                words.append("three")
            elif d == 4:
                words.append("four")
            elif d == 5:
                words.append("five")
            elif d == 6:
                words.append("six")
            elif d == 7:
                words.append("seven")
            elif d == 8:
                words.append("eight")
            elif d == 9:
                words.append("nine")
            elif d == 0:
                pass
            else:
                raise ValueError("Invalid digit")
        return " ".join(reversed(words))
    else:
        return f"minus {english_number_to_words(-n)}"

# Test cases
print(english_number_to_words(123))  # Output: one hundred twenty-three
print(english_number_to_words(-456))  # Output: minus four hundred fifty-six
print(english_number_to_words(007))  # Output: zero seven
print(english_number_to_words(1234567890))  # Output: one billion two hundred thirty-four million five hundred sixty-seven thousand eight hundred ninety

# Scientific notation input
print(english_number_to_words(1e3))  # Output: one thousand
print(english_number_to_words(1e-3))  # Output: one millimeter

