          image: 'django:4.0-slim-buster',
          memoryLimitMiB: 512,
          essential: true,
        },
      ],
    });

    const service = new ecs.Service(this, 'Service', {
      cluster,
      taskDefinition,
    });

    // Configure the React app container
    const reactContainer = service.taskDefinition.containerDefinitions[0];
    reactContainer.addPortMappings({
      containerPort: 3000,
    });

