import { useCombobox } from 'downshift';

const EmailInputField = () => {
  const [emails, setEmails] = React.useState([]);
  const [searchTerm, setSearchTerm] = React.useState('');

  const searchEmails = async (prefix: string) => {
    // Replace this with your actual API call or logic to fetch emails
    const mockEmails = ['john@example.com', 'jane@example.com', 'bob@example.com'];
    const filteredEmails = mockEmails.filter((email) => email.startsWith(prefix));
    setEmails(filteredEmails);
  };

  const { isOpen, selectedItem, getMenuProps, getInputProps, getComboboxProps } = useCombobox({
    items: emails,
    getItemToString: (item) => item,
    onSelect: (selectedItem) => setSelectedItem(selectedItem),
    onInputValueChange: (inputValue) => setSearchTerm(inputValue),
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      <ul {...getMenuProps()}>
        {isOpen &&
          emails.map((email) => (
            <li key={email} {...getMenuItemProps({ item: email })}>
              {email}
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailInputField;
```

