```typescript
const data = [10, 20, 30, 40, 50];

function generateBarChart(data: number[]): void {
  const canvas = document.createElement('canvas');
  canvas.width = 400;
  canvas.height = 200;

  const ctx = canvas.getContext('2d');

  // Set the background color
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Set the bar color
  ctx.fillStyle = 'blue';

  // Calculate the bar width and height
  const barWidth = canvas.width / data.length;
  const barHeight = data.reduce((a, b) => Math.max(a, b), 0);

  // Draw the bars
  for (let i = 0; i < data.length; i++) {
    const x = i * barWidth;
    const y = canvas.height - barHeight * data[i] / barHeight;
    ctx.fillRect(x, y, barWidth, barHeight * data[i] / barHeight);
  }

  // Add a label to the chart
  ctx.fillStyle = 'black';
  ctx.font = '16px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Dataset', canvas.width / 2, canvas.height / 2);

  // Add the chart to the HTML page
  document.body.appendChild(canvas);
}

generateBarChart(data);
```

```typescript
import * as d3 from 'd3';

const data: { [key: string]: number }[] = [
  { name: 'A', value: 20 },
  { name: 'B', value: 30 },
  { name: 'C', value: 40 },
];

const margin = { top: 20, right: 20, bottom: 30, left: 40 };
const width = 960 - margin.left - margin.right;
const height = 500 - margin.top - margin.bottom;

const x = d3.scaleBand()
  .domain(data.map((d) => d.name))
  .range([0, width]);

const y = d3.scaleLinear()
  .domain([0, d3.max(data, (d) => d.value)])
  .range([height, 0]);

const bar = d3.select('#chart')
  .append('g')
  .attr('transform', `translate(${margin.left}, ${margin.top})`);

bar.append('rect')
  .attr('class', 'bar')
  .attr('x', 0)
  .attr('y', (d) => y(d.value))
  .attr('width', x.bandwidth())
  .attr('height', (d) => height - y(d.value));

bar.append('text')
  .attr('class', 'bar-label')
  .attr('x', x.bandwidth() / 2)
  .attr('y', (d) => y(d.value) + 10)
  .attr('text-anchor', 'middle')
  .text((d) => d.value);
```

