def find_longest_word(s: str) -> str:
    words = s.split()
    max_length = 0
    result = ""

    for word in words:
        if len(word) > max_length:
            max_length = len(word)
            result = word
        elif len(word) == max_length:
            if word < result:
                result = word

    return result
